create table internal.specialist_sandbox_payment_evidence (session_id text primary key check(left(session_id,8)='cs_test_'),event_id text not null,course_id text not null,price_id text not null,terms_version text not null,consent_at timestamptz not null,verified_at timestamptz not null default now());
alter table internal.specialist_sandbox_payment_evidence enable row level security;
revoke all on internal.specialist_sandbox_payment_evidence from public,anon,authenticated;
create or replace function public.record_specialist_sandbox_payment(p_session text,p_event text,p_course text,p_price text,p_version text,p_consent timestamptz) returns boolean language plpgsql security definer set search_path to '' as $$
begin
 if p_session is null or left(p_session,8)<>'cs_test_' or p_event is null or left(p_event,4)<>'evt_' or p_version is distinct from 'specialist-2026-11-27-v1' or p_consent is null or p_consent>now() or not exists(select 1 from (values ('bu-01','price_1UgUjJ3eiZFnd5l0cE2PPZNM'),('bu-02','price_1UgUjR3eiZFnd5l0h5GTxICs'),('bu-03','price_1UgUjS3eiZFnd5l0Mdw7nh1m'),('bu-04','price_1UgUjU3eiZFnd5l0T1gBMEOS'),('bu-05','price_1UgUjW3eiZFnd5l0bpAyARi5'),('bu-06','price_1UgUjX3eiZFnd5l0Q0XTeg8C'),('la-01','price_1UgUju3eiZFnd5l0989tyQHT'),('la-02','price_1UgUk43eiZFnd5l0RaHcz1MV'),('la-03','price_1UgUk53eiZFnd5l0NGdD5gkG'),('la-04','price_1UgUk73eiZFnd5l0fao8ENqK'),('la-05','price_1UgUk83eiZFnd5l07lxVKcPA'),('la-06','price_1UgUkA3eiZFnd5l0r1N6OJkp'),('ms-01','price_1UgUjj3eiZFnd5l0pPXpDTJA'),('ms-02','price_1UgUjl3eiZFnd5l0W0rfJZab'),('ms-03','price_1UgUjn3eiZFnd5l0fPKr7Lux'),('ms-04','price_1UgUjo3eiZFnd5l0Y95xaNzj'),('ms-05','price_1UgUjq3eiZFnd5l0Oqoq6dCL'),('ms-06','price_1UgUjs3eiZFnd5l0E3BeJZSe'),('ts-01','price_1UgUjZ3eiZFnd5l0g1dXmLJ6'),('ts-02','price_1UgUjb3eiZFnd5l0rmn5O330'),('ts-03','price_1UgUjc3eiZFnd5l0bVIxp6LZ'),('ts-04','price_1UgUje3eiZFnd5l0HdigXuNT'),('ts-05','price_1UgUjg3eiZFnd5l0TbAD5DmP'),('ts-06','price_1UgUji3eiZFnd5l0y2LV8Zzf')) as allowed(course,price) where allowed.course=p_course and allowed.price=p_price) then return false; end if;
 insert into internal.specialist_sandbox_payment_evidence(session_id,event_id,course_id,price_id,terms_version,consent_at) values(p_session,p_event,p_course,p_price,p_version,p_consent) on conflict(session_id) do nothing;
 return exists(select 1 from internal.specialist_sandbox_payment_evidence where session_id=p_session and course_id=p_course and price_id=p_price and terms_version=p_version and consent_at=p_consent);
end $$;
revoke all on function public.record_specialist_sandbox_payment(text,text,text,text,text,timestamptz) from public,anon,authenticated;
grant execute on function public.record_specialist_sandbox_payment(text,text,text,text,text,timestamptz) to service_role;